def require(ok, message):
    if not ok:
        raise ValueError(message)


def boundary(value, path='$'):
    if isinstance(value, dict):
        require(path in PUBLIC_SHAPES, 'Unknown public object: ' + path)
        require(any(set(value) == set(fields) for fields in PUBLIC_SHAPES[path]), 'Public projection fields changed: ' + path)
        for key, child in value.items():
            boundary(child, path + '.' + key)
    elif isinstance(value, list):
        for child in value:
            boundary(child, path + '[]')
    elif isinstance(value, float):
        require(math.isfinite(value), 'Nonfinite public value')


def validate(d):
    boundary(d)
    raw = json.dumps(d, ensure_ascii=False, allow_nan=False)
    require(not re.search(r's3://|/home/|/workspace/|sagemaker|arn:aws|api[_-]?key|secret[_-]?key|circa|"model_id"|"policy_id"|"game_id"|owner_relative_path|feature_names|raw_quotes|\.pyz', raw, re.I), 'Private or out-of-scope material')
    require(d['schema'] == 'fbs.public.completed.v099.v1' and d['owner'] == 'FBS', 'Wrong report identity')
    require(d['publication'] == {'source_snapshot': True, 'website_deployment_claimed': False, 'model_promotion': False}, 'Publication cannot promote models or claim website deployment')
    o, s = d['operations'], d['science']
    require(o['owner'] == s['owner'] == 'FBS' and o['run_id'] == s['run_id'] == d['run_id'], 'Evidence invocation mismatch')
    require(o['operational_status'] == 'VERIFIED_RETURN_PUBLICATION_FINISHED' and o['owner_execution_successful'], 'Actual verified finish required')
    require(o['scientific_status'] == 'VERIFIED_PARTIAL_RESUMABLE_V13' and not o['full_v13_program_complete'], 'Finite finish cannot claim full V13 completion')
    require(o['return']['integrity_verified'] and o['return']['durable_publication_verified'], 'Verified return required')
    require(o['return']['parts'] == 1 and o['return']['bytes'] == 72561442 and o['return']['bytes'] <= o['return']['maximum_part_bytes'] == 536870912, 'Compact return identity changed')
    require(o['return']['sha256'] == '130dd0d07d571597e5de02ad9f576859d8f36d8322666687f47062c61ba86667', 'Return digest mismatch')
    require((o['science']['registered_scoring_tasks'], o['science']['completed_scoring_tasks'], o['science']['scoring_failures']) == (600, 600, 0), 'Scoring completion differs')
    require(o['science']['v098_fitting_jobs_authenticated_and_preserved'] == 1125, 'Completed V098 work must be preserved')
    require(o['science']['new_model_fits'] == o['science']['new_calibrator_fits'] == o['science']['new_optimizer_entries'] == 0, 'Scoring cannot become fitting')
    require(o['science']['selection_locked_before_test'] and not o['science']['test_outcomes_used_for_selection'] and not o['science']['training_season_weights_changed'], 'Validation/test separation changed')
    require(o['science']['prior_2026_test_exposure_disclosed'] and not o['science']['production_deployed'], 'Exposure or promotion boundary changed')
    require(s['outcome']['scientific_complete'] is False and s['outcome']['total_policy_count'] == 934, 'Broader science remains partial')
    require(s['outcome']['existing_policy_count'] == 834 and s['outcome']['new_policy_count'] == 100, 'Additive policy counts changed')
    require(s['outcome']['completed_forecast_tasks'] == 300 and s['outcome']['completed_uncertainty_tasks'] == 300, 'Finite task counts changed')
    require(s['outcome']['new_fits'] == s['outcome']['failed_scoring_tasks'] == 0, 'Fitting or failure accounting changed')
    require(s['outcome']['profiles'] == PROFILES and s['outcome']['primary_profile'] == '50/50', 'Evaluation profiles changed')
    require(s['outcome']['validation_seasons'] == [2024, 2025] and s['outcome']['test_season'] == 2026, 'Selection seasons changed')
    require(s['outcome']['test_used_for_selection'] is False and s['outcome']['season_training_weights'] is False and s['outcome']['sensitivity_refits'] == 0, 'Test outcomes or training weights cannot select models')
    require(s['outcome']['test_previously_exposed'] is True and s['outcome']['original_issued'] is False and s['outcome']['promotion'] is False, 'Reconstruction, exposure or promotion claim changed')

    leaders = s['leaders']
    require(len(leaders) == 45 and {(r['profile'], r['target'], r['objective']) for r in leaders} == {(p, t, m) for p in PROFILES for t, m in OBJECTIVES}, 'All five profiles and nine objectives required')
    same_candidate = {}
    for row in leaders:
        require(row['origin'] in ('V098', 'V099') and row['primary'] == (row['profile'] == '50/50'), 'Primary profile or origin differs')
        require(re.fullmatch(r'T60 research \d{2}', row['model_alias']) is not None, 'Only opaque public aliases are allowed')
        require([a['season'] for a in row['annual']] == [2024, 2025, 2026], 'Validation/test seasons differ')
        require([a['expected_n'] for a in row['annual']] == [919, 934, 755], 'Eligible populations cannot shrink')
        require(all(a['expected_n'] == a['scored_n'] and a['missing_n'] == 0 and a['complete_coverage'] for a in row['annual']), 'Incomplete contender population')
        values = [a['metric'] for a in row['annual']]
        require(all(type(v) in (int, float) and math.isfinite(v) and v >= 0 for v in values), 'Invalid metric')
        weight = int(row['profile'].split('/')[0]) / 100
        require(math.isclose(row['validation_score'], weight * values[0] + (1 - weight) * values[1], rel_tol=1e-12, abs_tol=1e-12), 'Selection score must use 2024/2025 only')
        key = (row['model_alias'], row['target'], row['objective'])
        require(key not in same_candidate or same_candidate[key] == values, 'Changing evaluation weights changed base predictions')
        same_candidate[key] = values
    require([(p['season'], p['observed_n'], p['completed_n'], p['pending_n']) for p in s['population']] == [(2024, 920, 919, 1), (2025, 934, 934, 0), (2026, 888, 755, 133)], 'Full observed population denominators changed')
    require(all(p['full_census_certified'] is False for p in s['population']), 'Unproved official census')
    source = s['source_coverage']
    require(source['qualified_cells'] + source['missing_cells'] + source['outside_history_cells'] == source['total_cells'] == 412371, 'Source grid must reconcile')
    require(len(source['coverage']) == 9, 'Target-season source coverage incomplete')
    for row in source['coverage']:
        require(row['qualified_n'] + row['all_sources_absent_n'] == row['observed_n'] == {2024: 920, 2025: 934, 2026: 888}[row['season']], 'Source denominator cannot shrink')
    u = s['uncertainty']
    require(u['replicates'] == 4096 and u['completed_comparisons'] == sum(x['comparisons'] for x in u['summary_by_target_objective_season']) == 900, 'Uncertainty comparison counts do not reconcile')
    require(u['improved_comparisons_holm_p_below_0_05'] == sum(x['holm_p_below_0_05_improved'] for x in u['summary_by_target_objective_season']) == 0, 'Unsupported significance claim')
    require(u['worse_comparisons_holm_p_below_0_05'] == sum(x['holm_p_below_0_05_worse'] for x in u['summary_by_target_objective_season']) == 373, 'Uncertainty negative findings must be retained')
    require(all(x['paired_n'] == {2024:919, 2025:934, 2026:755}[x['season']] for x in u['summary_by_target_objective_season']), 'Uncertainty cohort shrank')
    cpu = o['cpu']
    require(cpu['admitted_worker_capacity'] == cpu['max_workers_hard_ceiling'] == 36 and cpu['native_threads_per_worker'] == 1, 'Runtime capacity differs')
    require(cpu['full_capacity_pass'] is False and cpu['optimizer_occupancy_claimed'] is False, 'Admitted workers cannot become actual CPU or fitted work')
    require(cpu['sustained_75_percent_180_second_gate'] == 'NOT_APPLICABLE_FINITE_QUEUE_UNDER_180S', 'Short queue cannot claim sustained acceptance')
    require(sum(p['completed_tasks'] for p in cpu['pipelines']) == 600 and all(p['failed_tasks'] == 0 for p in cpu['pipelines']), 'Pipeline counts do not reconcile')
    for p in cpu['pipelines']:
        require(p['gate']['full_capacity_pass'] is False and p['gate']['eligible_windows'] == 0 and p['gate']['prior_v098_acceptance_inherited'] is False, 'Prior or short-window CPU cannot count as sustained pass')
        require(math.isclose(p['mean_useful_scoring_cpu_cores'], p['useful_scoring_worker_cpu_seconds'] / p['dispatch_wall_seconds'], rel_tol=1e-12), 'Actual CPU calculation changed')
    payload = o['payloads']
    require(payload['completed_new_unique_payloads'] == payload['new_unique_payload_count'] == 1528, 'New unique payload counters must reconcile')
    require(payload['new_uploaded_bytes'] == 65668678 and payload['whole_parent_archive_downloads'] == 0, 'Payload publication accounting changed')
    require(len(o['stages']) == 16 and [x['number'] for x in o['stages']] == list(range(1, 17)), 'Sixteen authoritative stages required')
    require(all(x['status'] in ('Authenticated completed', 'Reused') and x['completed'] == x['total'] for x in o['stages']), 'Uncompleted stage cannot be shown as complete')
    require(o['stage_manifest_interpretation']['completed_or_reused_stages'] == 16 and o['stage_manifest_interpretation']['zip_snapshot_current_stage'] == 12, 'Immutable archive snapshot and final supervisor manifest differ intentionally')
    require(not o['separate_refused_attempt']['counted_as_owner_research_failure'] and o['separate_refused_attempt']['exit_code'] == 75, 'Duplicate launch refusal is distinct')
    cost = o['cost']
    require(not cost['estimate_is_invoice'] and math.isclose(cost['estimate_usd'], cost['measured_seconds'] * cost['rate_usd_per_full_host_hour'] / 3600, rel_tol=1e-12), 'Compute estimate is not an invoice')
    require(s['evidence']['return_sha256'] == o['return']['sha256'], 'Science and operations return differ')
    return d


